// ServerInterface represents all server handlers.
type ServerInterface interface {
	// GetHealth Liveness probe
	// (GET /healthz)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// GetReady Readiness probe (DB reachable)
	// (GET /readyz)
	GetReady(w http.ResponseWriter, r *http.Request)

	// (GET /v1/admin/groups)
	AdminListGroups(w http.ResponseWriter, r *http.Request)

	// (PUT /v1/admin/groups/{groupId}/limits)
	AdminSetGroupLimits(w http.ResponseWriter, r *http.Request, groupId GroupId)
	// AgentEnrollDevice Start device-code enrollment (unsigned; no node yet).
	// (POST /v1/agent/enroll/device)
	AgentEnrollDevice(w http.ResponseWriter, r *http.Request)

	// (POST /v1/agent/enroll/device/poll)
	AgentEnrollDevicePoll(w http.ResponseWriter, r *http.Request)

	// (POST /v1/agent/enroll/token)
	AgentEnrollToken(w http.ResponseWriter, r *http.Request)

	// (POST /v1/agent/executions/{executionId}/logs)
	AgentExecutionLogs(w http.ResponseWriter, r *http.Request, executionId string)

	// (POST /v1/agent/executions/{executionId}/status)
	AgentExecutionStatus(w http.ResponseWriter, r *http.Request, executionId string)

	// (POST /v1/agent/heartbeat)
	AgentHeartbeat(w http.ResponseWriter, r *http.Request)

	// (POST /v1/agent/snapshots)
	AgentCreateSnapshot(w http.ResponseWriter, r *http.Request)

	// (POST /v1/agent/snapshots/{snapshotId}/replicas)
	AgentReplicaReady(w http.ResponseWriter, r *http.Request, snapshotId string)

	// (POST /v1/auth/login)
	Login(w http.ResponseWriter, r *http.Request)

	// (POST /v1/auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// Signup Create an account. First user becomes operator.
	// (POST /v1/auth/signup)
	Signup(w http.ResponseWriter, r *http.Request)

	// (POST /v1/device-links/approve)
	ApproveDeviceLink(w http.ResponseWriter, r *http.Request)

	// (GET /v1/device-links/{userCode})
	GetDeviceLink(w http.ResponseWriter, r *http.Request, userCode string)

	// (GET /v1/games)
	ListGames(w http.ResponseWriter, r *http.Request)

	// (GET /v1/groups)
	ListGroups(w http.ResponseWriter, r *http.Request)

	// (POST /v1/groups)
	CreateGroup(w http.ResponseWriter, r *http.Request)

	// (DELETE /v1/groups/{groupId})
	DeleteGroup(w http.ResponseWriter, r *http.Request, groupId GroupId)

	// (GET /v1/groups/{groupId})
	GetGroup(w http.ResponseWriter, r *http.Request, groupId GroupId)

	// (PATCH /v1/groups/{groupId})
	UpdateGroup(w http.ResponseWriter, r *http.Request, groupId GroupId)

	// (GET /v1/groups/{groupId}/enrollment-tokens)
	ListEnrollmentTokens(w http.ResponseWriter, r *http.Request, groupId GroupId)

	// (POST /v1/groups/{groupId}/enrollment-tokens)
	CreateEnrollmentToken(w http.ResponseWriter, r *http.Request, groupId GroupId)

	// (DELETE /v1/groups/{groupId}/enrollment-tokens/{tokenId})
	DeleteEnrollmentToken(w http.ResponseWriter, r *http.Request, groupId GroupId, tokenId string)

	// (GET /v1/groups/{groupId}/events)
	ListEvents(w http.ResponseWriter, r *http.Request, groupId GroupId, params ListEventsParams)

	// (GET /v1/groups/{groupId}/events/stream)
	StreamEvents(w http.ResponseWriter, r *http.Request, groupId GroupId)

	// (POST /v1/groups/{groupId}/invites)
	CreateInvite(w http.ResponseWriter, r *http.Request, groupId GroupId)

	// (GET /v1/groups/{groupId}/members)
	ListMembers(w http.ResponseWriter, r *http.Request, groupId GroupId)

	// (DELETE /v1/groups/{groupId}/members/{userId})
	RemoveMember(w http.ResponseWriter, r *http.Request, groupId GroupId, userId UserId)

	// (PATCH /v1/groups/{groupId}/members/{userId})
	UpdateMember(w http.ResponseWriter, r *http.Request, groupId GroupId, userId UserId)

	// (GET /v1/groups/{groupId}/nodes)
	ListNodes(w http.ResponseWriter, r *http.Request, groupId GroupId)

	// (GET /v1/groups/{groupId}/servers)
	ListServers(w http.ResponseWriter, r *http.Request, groupId GroupId)

	// (POST /v1/groups/{groupId}/servers)
	CreateServer(w http.ResponseWriter, r *http.Request, groupId GroupId)

	// (GET /v1/invites/{code})
	GetInvite(w http.ResponseWriter, r *http.Request, code string)

	// (POST /v1/invites/{code}/accept)
	AcceptInvite(w http.ResponseWriter, r *http.Request, code string)

	// (GET /v1/me)
	GetMe(w http.ResponseWriter, r *http.Request)

	// (DELETE /v1/nodes/{nodeId})
	DeleteNode(w http.ResponseWriter, r *http.Request, nodeId NodeId)

	// (GET /v1/nodes/{nodeId})
	GetNode(w http.ResponseWriter, r *http.Request, nodeId NodeId)

	// (PATCH /v1/nodes/{nodeId})
	UpdateNode(w http.ResponseWriter, r *http.Request, nodeId NodeId)
	// GetRelayPublicKey ed25519 public key used to sign relay tokens
	// (GET /v1/relay/public-key)
	GetRelayPublicKey(w http.ResponseWriter, r *http.Request)

	// (DELETE /v1/servers/{serverId})
	DeleteServer(w http.ResponseWriter, r *http.Request, serverId ServerId)

	// (GET /v1/servers/{serverId})
	GetServer(w http.ResponseWriter, r *http.Request, serverId ServerId)

	// (PATCH /v1/servers/{serverId})
	UpdateServer(w http.ResponseWriter, r *http.Request, serverId ServerId)

	// (GET /v1/servers/{serverId}/executions)
	ListExecutions(w http.ResponseWriter, r *http.Request, serverId ServerId)

	// (GET /v1/servers/{serverId}/logs)
	GetServerLogs(w http.ResponseWriter, r *http.Request, serverId ServerId, params GetServerLogsParams)

	// (POST /v1/servers/{serverId}/move)
	MoveServer(w http.ResponseWriter, r *http.Request, serverId ServerId)

	// (GET /v1/servers/{serverId}/snapshots)
	ListSnapshots(w http.ResponseWriter, r *http.Request, serverId ServerId)

	// (POST /v1/servers/{serverId}/snapshots)
	RequestSnapshot(w http.ResponseWriter, r *http.Request, serverId ServerId)

	// (POST /v1/servers/{serverId}/start)
	StartServer(w http.ResponseWriter, r *http.Request, serverId ServerId)

	// (POST /v1/servers/{serverId}/stop)
	StopServer(w http.ResponseWriter, r *http.Request, serverId ServerId)

	// (PATCH /v1/snapshots/{snapshotId})
	UpdateSnapshot(w http.ResponseWriter, r *http.Request, snapshotId string)
	// GetVersion Control-plane build version
	// (GET /v1/version)
	GetVersion(w http.ResponseWriter, r *http.Request)
}

// ServerInterfaceWrapper converts contexts to parameters.
type ServerInterfaceWrapper struct {
	Handler            ServerInterface
	HandlerMiddlewares []MiddlewareFunc
	ErrorHandlerFunc   func(w http.ResponseWriter, r *http.Request, err error)
}

type MiddlewareFunc func(http.Handler) http.Handler

